import re
import six

from pyparsing import Regex, Literal, Optional, OneOrMore, Empty, ParseException, Group, Or as Or_


class ParameterPredicateSyntaxException(Exception):
    """ParameterPredicateSyntaxException is raised when parameter predicate has syntax errors."""


class ParameterPredicatesParser(object):

    param_name = OneOrMore(
        Regex('[^=, >, \], \[, \,, <, <=, >=, !=]+') + Optional(Regex("\[(0|[1-9][0-9]*|\*|\?)\]"))).setParseAction(lambda x: ''.join(x))('name')

    param_value_without_quotes = Regex('[^=, >, \], \[, \,, <, <=, >=, !=, "]+')('value')
    param_value_with_quotes = Literal('"') + OneOrMore(Regex('[^"]+')).setParseAction(lambda x: ' '.join(x))('value') + Literal('"')('quoted')
    param_value = (param_value_without_quotes | param_value_with_quotes)

    operator = Or_((Literal("=regex"), Literal("!=regex"), Literal('>'), Literal('<'),
                   Literal('>='), Literal('<='), Literal('='), Literal('!=')))('operator')
    empty_operator = Literal("=empty")('operator')
    non_empty_operator = Literal("!=empty")('operator')
    empty_value = Empty().setParseAction(lambda x: "")('value')

    predicate_body = Group(
        (param_name + (((empty_operator | non_empty_operator) + empty_value) | (operator + param_value))))(
        'predicate_body')
    predicate_content = Group((Optional(Literal(',')) + predicate_body)).setResultsName('predicates', True)

    grammar = OneOrMore(predicate_content)

    comparators = {
        '>': lambda x, y: x > y,
        '>=': lambda x, y: x >= y,
        '<': lambda x, y: x < y,
        '<=': lambda x, y: x <= y,
        '=': lambda x, y: x == y,
        '!=': lambda x, y: x != y,
        '=regex': lambda x, y: True if re.match(str(y), str(x)) else False,
        '!=regex': lambda x, y: False if re.match(str(y), str(x)) else True,
        '=empty': lambda x, y: not x and x != 0,
        '!=empty': lambda x, y: x or x == 0,
    }

    @classmethod
    def parse(self, parameters_expression):
        """Parse expression."""
        try:
            parsed_expression = self.grammar.parseString(parameters_expression)
        except ParseException as e:
            raise ParameterPredicateSyntaxException("%s in expression: '%s'" % (str(e), parameters_expression))

        predicates = []
        for predicate in parsed_expression.predicates:
            comparator = self.comparators[predicate.predicate_body.operator]
            param_locator = self._extract_location_parts(predicate.predicate_body.name)
            expected_value = predicate.predicate_body.value if predicate.predicate_body.quoted \
                else self._convert_value(predicate.predicate_body.value)
            predicates.append((param_locator, comparator, expected_value))

        return predicates

    @classmethod
    def _extract_location_parts(self, param_name):
        return [re.match(r'(?P<part>[^\[,\]]*)(\[(?P<index>.*)\])*', part).groups()[::2] for part in param_name.split('.')]

    @classmethod
    def _convert_value(self, value):
        converters = [self._to_bool, self._to_int, self._to_float, str]
        for converter in converters:
            try:
                return converter(value)
            except:
                pass
        raise Exception('Can not convert type of: %s' % value)

    @classmethod
    def _to_int(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, int):
            return value
        if isinstance(value, (six.string_types, six.binary_type)):
            try:
                return int(value)
            except ValueError:
                raise ValueError('Value "{}" is not an integer number representation'.format(str(value)))
        raise Exception('Object "{}" with value "{}" cannot be converted to int'.format(type(value).__name__, str(value)))

    @classmethod
    def _to_float(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, float):
            return value
        if isinstance(value, ((six.string_types, six.binary_type), int)):
            try:
                return float(value)
            except ValueError:
                raise ValueError('Value "{}" is not a floating point number representation'.format(str(value)))
        raise Exception('Object "{}" with value "{}" cannot be converted to float'.format(type(value).__name__, str(value)))

    @classmethod
    def _to_bool(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, bool):
            return value
        if isinstance(value, (six.string_types, six.binary_type)):
            return self._str_to_bool(value)
        raise Exception('Object "{}" with value "{}" cannot be converted to bool'.format(type(value).__name__, str(value)))

    @classmethod
    def _str_to_bool(self, value):
        if self._looks_like_true(value):
            value = True
        elif self._looks_like_false(value):
            value = False
        else:
            raise Exception('Value is from out of range. Available values are (not case sensitive): ${True}, ${False}, true, false')
        return value

    @classmethod
    def _looks_like_false(self, value):
        return value.lower().strip() == "false"

    @classmethod
    def _looks_like_true(self, value):
        return value.lower().strip() == "true"


class ObjectValidator(object):

    def __init__(self, parameters):
        self.predicates = ParameterPredicatesParser.parse(parameters) if parameters else []

    def check(self, payload):
        """Check object against parameters predicates."""
        if not payload or not isinstance(payload, dict):
            return False
        return all(self._check_value(locator, comp, expected_value, payload) for locator, comp, expected_value in self.predicates)

    def _check_value(self, param_locator, comparator, expected_value, source, depth=0):
        if depth == len(param_locator):
            return comparator(source, expected_value)

        name, index = param_locator[depth]
        try:
            source = source[name]
            return self._check_values_depending_on_type(param_locator, comparator, expected_value, source, index, depth)
        except (IndexError, KeyError, TypeError):
            return False

    def _check_values_depending_on_type(self, param_locator, comparator, expected_value, source, index, depth):
        if isinstance(source, list):
            return self._check_values_in_list(param_locator, comparator, expected_value, source, index, depth)
        elif isinstance(source, dict):
            depth += 1
            return self._check_value(param_locator, comparator, expected_value, source, depth)
        else:
            return comparator(source, expected_value)

    def _check_values_in_list(self, param_locator, comparator, expected_value, source, index, depth):
        depth += 1
        if index == "*":
            return all(self._check_value(param_locator, comparator, expected_value, s, depth) for s in source)
        elif index == "?":
            return any(self._check_value(param_locator, comparator, expected_value, s, depth) for s in source)
        elif self._is_numeric(index):
            return self._check_value(param_locator, comparator, expected_value, source[int(index)], depth)
        else:
            return comparator(source, expected_value)

    def _is_numeric(self, param):
        if not param:
            return False
        if hasattr(param, 'decode'):
            param = param.decode('ascii')
        if param.isnumeric():
            return True
        return False


class ObjectsValidator(object):

    def __init__(self, parameter_predicates):
        self.validator = ObjectValidator(parameter_predicates)

    def check(self, object_list):
        """Check objects against parameters predicates."""
        if not isinstance(object_list, list):
            return False
        return self._check_objects(object_list)

    def _check_objects(self, object_list):
        raise NotImplementedError


class AnyObjectValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        return any(self.validator.check(obj) for obj in object_list)


class AllObjectsValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        if not object_list:
            return False
        return all(self.validator.check(obj) for obj in object_list)


class NoneObjectsValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        return not any(self.validator.check(obj) for obj in object_list)
